release='83ff17075e9188dcf227c8752dc064248d5f42e0'
calc='4654386ca34f04041effe31f38259d0fae9c396ecda35c364e3a18dd125a4b90'
offer_pattern=r'/cars/offer/([a-f0-9]{20,30})'
class SameOrigin(urllib.request.HTTPRedirectHandler):
 def redirect_request(self, req, fp, code, msg, headers, newurl):
  if urllib.parse.urlsplit(newurl).netloc!='avtocena.com' or urllib.parse.urlsplit(newurl).scheme!='https':
   raise ValueError('public_acceptance_redirect_scope')
  return super().redirect_request(req,fp,code,msg,headers,newurl)
get=urllib.request.build_opener(SameOrigin()).open
def request(path):
 req=urllib.request.Request(origin+path,headers={'User-Agent':'Mozilla/5.0 AvtoCena catalog acceptance'})
 try:
  with get(req,timeout=16) as resp:
   b=resp.read(3*1024*1024+1)
   if len(b)>3*1024*1024: raise ValueError('public_acceptance_response_cap')
   return resp.status,b,resp.geturl()
 except urllib.error.HTTPError as e:
  if e.code not in (404,410): raise
  return e.code,b'',e.geturl()
def require(ok,code):
 if not ok: raise SystemExit(code)
def main(args):
 terminal=json.loads(pathlib.Path(args.terminal).read_text()) if args.terminal else {}
 if args.terminal:
  require(terminal.get('ok') is True and terminal.get('numeric',{}).get('passed') is True and terminal.get('pinPublished') is True and re.fullmatch(r'gen_\d+_[a-z0-9]+',terminal.get('generationId','')),'public_acceptance_uncommitted')
  require(len(terminal.get('sampleChinaIds',[]))==3,'public_acceptance_candidate_sample')
