 text=body.decode('utf-8');ids=list(dict.fromkeys(re.findall(offer_pattern,text)))
 require(len(ids)>=5,'public_acceptance_offer_links')
 require(not any(i in ids for i in sold),'public_acceptance_sold_link')
 sample=tuple(dict.fromkeys((*terminal.get('sampleChinaIds',[]),*args.sample,*ids[:3])))[:8]
 require(not set(sample).intersection(sold) and all(re.fullmatch('[a-f0-9]{20,30}',i) for i in sample),'public_acceptance_bad_sample')
 def card(i):return i,request('/cars/offer/'+i)
 with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
  checks=dict(pool.map(card,(*sold,*sample)))
 require(all(checks[i][0] in (404,410) for i in sold),'public_acceptance_sold_card')
 require(all(checks[i][0]==200 and (urllib.parse.urlsplit(checks[i][2]).path+'/').startswith('/cars/offer/'+i+'/') and len(checks[i][1])>5000 for i in sample),'public_acceptance_active_card')
 print(json.dumps({'siteAcceptancePassed':True,'generationId':terminal.get('generationId'),'releaseSha':release,'calculationVersion':calc,'soldChecked':len(sold),'sampledListingCards':len(sample),'visibleUniqueLinks':len(ids)}))
